import { Button } from '@refy-design/web';
import { Chip } from '@refy-design/web';
import { GuidedTour } from '@refy-design/web';
import { GuidedTourAnchor } from '@refy-design/web';
import type { GuidedTourStep } from '@refy-design/web';
import { Segmented } from '@refy-design/web';
import { useMemo } from 'react';
import { useState } from 'react';
function TourDemo({
  startStep = 'operation',
  initiallyOpen = true,
}: {
  startStep?: string;
  initiallyOpen?: boolean;
}) {
  const [open, setOpen] = useState(initiallyOpen);
  const [current, setCurrent] = useState(startStep);
  const [operation, setOperation] = useState('create');
  const [types, setTypes] = useState(['document']);
  const [message, setMessage] = useState('Tour started.');
  const steps = useMemo<GuidedTourStep[]>(
    () => [
      {
        id: 'operation',
        title: 'Create or organize?',
        description: 'Start with the operation. You can change this choice later.',
        side: 'bottom',
        align: 'start',
      },
      {
        id: 'types',
        title: 'Choose more than one type',
        description: 'Documents and images can go together in the same search.',
        side: 'bottom',
        action: {
          label: types.includes('image')
            ? 'Image already selected'
            : 'Select Image now',
          onAction: () => {
            setTypes((value) =>
              value.includes('image') ? value : [...value, 'image'],
            );
            setMessage('The tour action selected Image in the real control.');
          },
        },
      },
      {
        id: 'continue',
        title: 'Continue when it makes sense',
        description: 'The request stays editable in the next wizard steps.',
        side: 'top',
        align: 'end',
      },
    ],
    [types],
  );
  return (
    <div
      style={{
        minHeight: 480,
        display: 'grid',
        alignContent: 'start',
        gap: 28,
        maxWidth: 760,
        padding: '28px 12px 180px',
      }}
    >
      <Button
        size="sm"
        variant="secondary"
        style={{ justifySelf: 'start' }}
        onClick={() => {
          setCurrent('operation');
          setOpen(true);
          setMessage('Tour restarted.');
        }}
      >
        Restart tour
      </Button>
      <GuidedTour
        steps={steps}
        open={open}
        currentStep={current}
        onOpenChange={setOpen}
        onStepChange={setCurrent}
        onComplete={() => setMessage('Tour finished.')}
      >
        <div style={{ display: 'grid', gap: 24 }}>
          <GuidedTourAnchor stepId="operation">
            <Segmented
              label="Operation"
              value={operation}
              onChange={setOperation}
              options={[
                { value: 'create', label: 'Create' },
                { value: 'organize', label: 'Organize' },
              ]}
            />
          </GuidedTourAnchor>

          <GuidedTourAnchor stepId="types" block>
            <div
              role="group"
              aria-label="Content formats"
              style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}
            >
              {['document', 'image', 'video'].map((type) => (
                <Chip
                  key={type}
                  selected={types.includes(type)}
                  showCheck
                  onClick={() =>
                    setTypes((value) =>
                      value.includes(type)
                        ? value.filter((item) => item !== type)
                        : [...value, type],
                    )
                  }
                >
                  {type[0].toUpperCase() + type.slice(1)}
                </Chip>
              ))}
            </div>
          </GuidedTourAnchor>

          <GuidedTourAnchor stepId="continue">
            <Button
              variant="primary"
              onClick={() =>
                setMessage('The real control would move on to the wizard.')
              }
            >
              Continue
            </Button>
          </GuidedTourAnchor>
        </div>
      </GuidedTour>
      <p
        role="status"
        style={{ margin: 0, color: 'var(--ink-3)', fontSize: 'var(--text-xs)' }}
      >
        {message}
      </p>
    </div>
  );
}
export function Example() {
  return <TourDemo />;
}

